# NDCG@k: a listwise metric. Position discounts make the top of the list matter most.
import math

def dcg(rels):
    # gain 2^rel - 1, discounted by log2(position + 1)
    return sum((2 ** r - 1) / math.log2(i + 2) for i, r in enumerate(rels))

def ndcg(rels, k):
    ideal = sorted(rels, reverse=True)
    return dcg(rels[:k]) / dcg(ideal[:k])

good = [3, 2, 0, 1]   # relevance labels in the order the ranker returned them
bad = [0, 1, 2, 3]    # same documents, reversed order
print("ranking A:", good, "NDCG@4 =", round(ndcg(good, 4), 3))
print("ranking B:", bad, "NDCG@4 =", round(ndcg(bad, 4), 3))

# pairwise view: count document pairs that are in the wrong order
def inversions(rels):
    return sum(1 for i in range(len(rels)) for j in range(i + 1, len(rels)) if rels[i] < rels[j])
print("wrong pairs A:", inversions(good), " B:", inversions(bad))
# the sort inside ndcg() makes the metric non-differentiable, which is why it is hard to optimise directly

# Feedback loop: a greedy recommender starves a good new item; epsilon exploration fixes it.
import random

def run(eps, steps=2000, seed=1):
    rng = random.Random(seed)
    true_ctr = {"old_hit": 0.10, "new_better": 0.15}
    shown = {k: 1 for k in true_ctr}
    clicks = {"old_hit": 1, "new_better": 0}   # the old item has history, the new one has none
    for _ in range(steps):
        if rng.random() < eps:
            item = rng.choice(list(true_ctr))               # explore
        else:
            item = max(true_ctr, key=lambda k: clicks[k] / shown[k])  # exploit estimate
        shown[item] += 1
        clicks[item] += rng.random() < true_ctr[item]
    return shown

for eps in (0.0, 0.1):
    s = run(eps)
    print("epsilon", eps, "impressions:", s)
# with eps=0 the new item gets almost no exposure, so its data never arrives
